export const merklClaimableRewardAmountRegExp = new RegExp('^\\d+$');
export const merklClaimableRewardClaimedRegExp = new RegExp('^\\d+$');
export const merklClaimableRewardPendingRegExp = new RegExp('^\\d+$');

const merklClaimableRewardImplementation = zod
    .object({
        root: zod.string().describe('Merkl root committing this reward distribution'),
        amount: zod
            .string()
            .regex(merklClaimableRewardAmountRegExp)
            .describe('Total reward amount accrued (smallest denomination)'),
        claimed: zod
            .string()
            .regex(merklClaimableRewardClaimedRegExp)
            .describe('Amount already claimed (smallest denomination)'),
        pending: zod
            .string()
            .regex(merklClaimableRewardPendingRegExp)
            .describe('Pending reward amount (smallest denomination)'),
        token: MerklTokenRef,
        proofs: zod.array(zod.string()).describe('Merkl proof nodes for claiming'),
    })
    .meta({ id: 'MerklClaimableReward' });

export type MerklClaimableReward = zod.input<typeof merklClaimableRewardImplementation>;
export type MerklClaimableRewardOutput = zod.output<typeof merklClaimableRewardImplementation>;

