export type GetYieldResponse = zod.input<typeof getYieldResponseImplementation>;
export type GetYieldResponseOutput = zod.output<typeof getYieldResponseImplementation>;

export interface GetYieldResponseSchema extends zod.ZodType<
    GetYieldResponseOutput,
    GetYieldResponse
> {}

export const GetYieldResponse: GetYieldResponseSchema = getYieldResponseImplementation;

/**
 * @deprecated
 * @summary Generate transactions to enter a yield position
 */
export const enterYieldHeaderXSuiteVersionRegExp = new RegExp('^(\\d+)\\.(\\d+)\\.(\\d+)$');

const enterYieldHeaderImplementation = zod.object({
    'x-suite-version': zod
        .string()
        .regex(enterYieldHeaderXSuiteVersionRegExp)
        .describe('Caller suite semver (e.g. 25.10.0). Used to scope vault allow-list.'),
});

export type EnterYieldHeader = zod.input<typeof enterYieldHeaderImplementation>;
export type EnterYieldHeaderOutput = zod.output<typeof enterYieldHeaderImplementation>;

export interface EnterYieldHeaderSchema extends zod.ZodType<
    EnterYieldHeaderOutput,
    EnterYieldHeader
> {}

export const EnterYieldHeader: EnterYieldHeaderSchema = enterYieldHeaderImplementation;

const enterYieldBodyImplementation = CreateActionDto;

export type EnterYieldBody = zod.input<typeof enterYieldBodyImplementation>;
export type EnterYieldBodyOutput = zod.output<typeof enterYieldBodyImplementation>;

export interface EnterYieldBodySchema extends zod.ZodType<EnterYieldBodyOutput, EnterYieldBody> {}

export const EnterYieldBody: EnterYieldBodySchema = enterYieldBodyImplementation;

